-- ============================================================
-- 0130_testing_norms_v2.sql
-- ============================================================
-- Youth testing norms v2, from salopia_report_engine2.py (Oct 2026).
--
-- 1. A fifth rating, Elite, above Excellent: test_benchmarks gets an
--    elite_threshold (null = the metric has no Elite tier - only the
--    four tests below have one so far), and test_metrics a
--    commentary_elite. The engine's 4-tuples are now four real
--    thresholds (NW/Avg, Avg/Good, Good/Exc, Exc/Elite); 0027 dropped
--    the first value, so every rating moves up one tier.
-- 2. New norms for 10m Sprint, CMJ, RSI (10-5) and IMTP Relative
--    (N/kg), incl. an adult (19+) band, with each norm's data quality
--    (strong / moderate / sparse) and sources. Replaces those four
--    metrics' benchmarks in EVERY organisation.
-- 3. DSI: two new metrics - CMJ Peak Force (kg) and DSI (CMJ/IMTP) -
--    added to every org's youth battery. DSI is worked out in the app
--    and zoned (Strength Focus / Balanced / Power Focus), not rated.
-- 4. seed_youth_battery(org) + a trigger, so organisations created
--    from now on get the youth battery with these norms (0027 only
--    seeded the orgs that existed then; 0082 did the same for FMS).
-- Safe to re-run.
-- ============================================================

alter table test_benchmarks add column if not exists elite_threshold numeric;
alter table test_benchmarks add column if not exists quality text check (quality in ('strong', 'moderate', 'sparse'));
alter table test_benchmarks add column if not exists sources text;
alter table test_metrics add column if not exists commentary_elite text not null default '';

-- Template: the youth battery as it is live today (metric wording
-- copied from the existing orgs), with the v2 norms swapped in.
create or replace function youth_battery_template()
returns jsonb
language sql
immutable
set search_path = public
as $fn$
  select $tmpl${"battery":{"name":"Salopia Youth Testing Battery","description":"Standard youth physical testing battery — sprint, jump, strength, agility, and core tests with elite youth + general population benchmarks."},"metrics":[{"name":"10m Sprint","unit":"s","better_direction":"lower","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"The 10m sprint measures acceleration — the ability to generate speed rapidly from a standing start. This reflects neuromuscular explosiveness, stride mechanics, and fast-twitch muscle fibre recruitment.","why_it_matters":"Acceleration underpins first-step quickness in virtually every sport — pressing, chasing, explosive changes of direction. One of the most important physical qualities in field and court sports.","notes":"","commentary":{"elite":"Elite acceleration - at the very top of trained youth athletes their age. Protect it with high-quality, low-volume sprint work and keep building the strength base underneath it.","excellent":"Excellent acceleration for elite youth athletes. Among the fastest in their age group in a trained population. Maintain with sprint mechanics and lower-body power work.","good":"Good acceleration for their age. A solid foundation — progressive sprint training and plyometrics will continue to develop this quality.","average":"Average acceleration for their age. Sprint mechanics coaching, resisted sprints, and lower-body power development should be prioritised in the next training block.","needs_work":"Below average acceleration for their age. Highly trainable — focused sprint technique work, plyometrics, and strength foundations will drive rapid improvement."}},{"name":"Countermovement Jump","unit":"cm","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"The Countermovement Jump (CMJ) measures lower-body explosive power and the stretch-shortening cycle — the ability to store elastic energy in a downward dip and release it explosively upward. Arms held on hips to isolate lower-body contribution.","why_it_matters":"Jump height reflects combined power output of the hips, knees, and ankles. Predicts sprint speed, change-of-direction ability, and overall athletic explosiveness.","notes":"","commentary":{"elite":"Elite jump height - at the very top of trained youth athletes their age. Keep plyometric quality high and volume controlled, and keep building strength so power has room to grow.","excellent":"Excellent jump height — explosive power well beyond age expectations. Continue with high-intensity plyometrics and progressive lower-body strength work.","good":"Good explosive power for their age. A strong platform — progress towards depth jumps and bounding, and increase lower-body strength loading.","average":"Average jump height for their age. Develop hip and knee extensor strength alongside progressive plyometric training.","needs_work":"Below average jump height for their age. Focus on fundamental lower-body strength and introduce basic plyometrics with quality mechanics before increasing intensity."}},{"name":"Reactive Strength Index (10-5)","unit":"m/s","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"Reactive Strength Index (RSI) via the 10-5 test measures the quality of the fast stretch-shortening cycle — how quickly an athlete can absorb ground impact and redirect force upward across 10 repeated maximal hops. Calculated as jump height divided by ground contact time (m/s).","why_it_matters":"RSI reflects tendon stiffness, neuromuscular timing, and plyometric capacity. Directly linked to sprint speed, agility, and resilience to lower-limb injury.","notes":"Not the same scale as CMJ-derived RSI-modified, which produces much lower values (~0.2-0.7 m/s) for the same athlete. Using RSImod norms here will badly under-rate athletes.","commentary":{"elite":"Elite reactive strength - exceptional stiffness and fast stretch-shortening ability for their age. Maintain with low-volume, high-quality reactive work and manage landing load carefully.","excellent":"Excellent RSI for elite youth athletes. Outstanding fast SSC capacity — continue with advanced reactive work (drop jumps, hurdle hops) emphasising minimal ground contact.","good":"Good RSI for their age. The reactive system is developing well. Continue with progressive plyometric loading, emphasising quick ground contact time.","average":"Average RSI for their age. Focus on ankle stiffness drills, pogo jumps, and plyometric progressions cued for quick ground contact.","needs_work":"Below average RSI for their age. Begin with ankle stiffness and pogo work before advancing to bounding and reactive plyometrics."}},{"name":"Squat Jump","unit":"cm","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"The Squat Jump (SJ) measures concentric-only lower-body explosive power. The athlete pauses at the bottom of the squat position for 2-3 seconds before jumping, removing the stretch-shortening cycle (SSC) contribution. Isolates pure force-generating capacity from a static position.","why_it_matters":"Comparing SJ with CMJ reveals how much an athlete benefits from the SSC. A large CMJ-SJ gap indicates good elastic energy storage. SJ also measures foundational leg strength and concentric power independent of reactive ability.","notes":"","commentary":{"elite":"","excellent":"Excellent squat jump height — strong concentric leg power and a solid force-producing foundation. Continue with progressive strength and explosive work.","good":"Good squat jump height for their age. A strong base — continue developing lower-body strength through compound movements alongside plyometric progressions.","average":"Average squat jump height for their age. Increasing lower-body strength work should be a priority — compound lifts such as squats and hip hinges will directly improve this quality.","needs_work":"Below average squat jump height for their age. Focus on building foundational lower-body strength through progressive compound movements before increasing jump training volume."}},{"name":"IMTP Peak Force (kg)","unit":"kg","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"The Isometric Mid Thigh Pull (IMTP) measures the maximum force an athlete can produce through the whole body in a static pull — engaging the legs, glutes, back, and grip simultaneously against a fixed bar. This row shows absolute peak force in kilograms.","why_it_matters":"The strength of the legs, glutes, back, and grip working together is one of the strongest predictors of speed, power, and injury resilience in young athletes. Athletes who can produce more total force have a significant advantage in virtually every sport.","notes":"Only shown when bodyweight is not recorded — prefer IMTP Relative (N/kg) whenever bodyweight is known. Never show both in the same report.","commentary":{"elite":"","excellent":"Excellent absolute peak force for their age — a strong result even accounting for body size differences. Continue with progressive compound movements to build on this.","good":"Good absolute peak force for their age. Continue developing with progressive compound lifts — deadlifts, trap bar and RDLs. Record bodyweight at the next session for a more precise relative strength comparison.","average":"Average absolute peak force for their age. Increasing strength work to improve force production should be a priority in the next training block. Record bodyweight at the next session for a relative strength comparison.","needs_work":"Below average absolute peak force for their age. Focus on building foundational strength through compound movements. Record bodyweight at the next session for a more precise comparison."}},{"name":"IMTP Relative (N/kg)","unit":"N/kg","better_direction":"higher","requires_bodyweight":true,"is_bilateral":false,"screening_only":false,"what_it_measures":"The Isometric Mid Thigh Pull (IMTP) measures the maximum force an athlete can produce through the whole body in a static pull — engaging the legs, glutes, back, and grip simultaneously against a fixed bar. This row expresses force relative to bodyweight (N/kg), the gold-standard comparison as it accounts for body size.","why_it_matters":"The strength of the legs, glutes, back, and grip working together is one of the strongest predictors of speed, power, and injury resilience in young athletes. Expressing this relative to bodyweight allows meaningful comparison across athletes of different sizes and ages.","notes":"Research found a moderate-large correlation (r=0.54-0.72) between grip strength and IMTP peak force in elite footballers — an athlete with strong compound lift numbers but a surprisingly low IMTP score may be grip-limited rather than genuinely weak through the legs/hips/back. Worth a retest with lifting straps if this pattern shows up.","commentary":{"elite":"Elite relative strength - at the very top of trained youth athletes their age. Focus on expressing that strength quickly (jumps, sprints, Olympic-lift variations) and keep monitoring left/right balance.","excellent":"Excellent relative strength for trained youth athletes of this age. A strong, powerful athlete — continue with progressive compound lifting and monitor for left-right asymmetries.","good":"Good relative strength for their age. A solid base — continue developing with progressive compound lifts including deadlifts, trap bar and Romanian deadlifts.","average":"Average relative strength for their age. Increasing strength work to improve force production should be a priority — introduce and progress compound lower-body and hip hinge movements with appropriate loading.","needs_work":"Below average relative strength for their age. Increasing strength work to improve force production is the key priority — focus on technical mastery of fundamental movements first, then build load consistently."}},{"name":"505 Change of Direction","unit":"s","better_direction":"lower","requires_bodyweight":false,"is_bilateral":true,"screening_only":false,"what_it_measures":"The 5-0-5 Change of Direction test measures the time to sprint 5m, perform a 180-degree turn, and sprint 5m back through the timing gate. Tested off each foot independently to screen for left-right asymmetries.","why_it_matters":"Change of direction speed is a critical performance quality in most field and court sports. Testing each leg separately reveals asymmetries that could indicate injury risk or movement deficiencies.","notes":"","commentary":{"elite":"","excellent":"Excellent change of direction speed for their age. A genuine athletic strength — maintain with reactive agility work and single-leg strength development.","good":"Good change of direction speed for their age. Continue developing with deceleration mechanics coaching and single-leg strength progressions.","average":"Average change of direction speed for their age. Focus on deceleration mechanics, single-leg strength, and reactive footwork patterns.","needs_work":"Below average change of direction speed. Prioritise deceleration and re-acceleration technique coaching, single-leg strength, and hip control."}},{"name":"Anterior Hold","unit":"s","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"The Anterior Hold measures endurance of the deep anterior core — transverse abdominis, rectus abdominis, and hip flexors — in maintaining a stable position against gravity. The athlete holds a specific position for as long as possible with good form.","why_it_matters":"Anterior core stability is essential for force transfer between the lower and upper body, spinal protection under load, and injury prevention at the hips and lower back. A fundamental quality for all athletes.","notes":"No published youth normative study exists for this test — practitioner benchmarks only, single age band 8-18.","commentary":{"elite":"","excellent":"Excellent anterior core endurance for trained youth. Strong stability — progress with weighted planks, hollow holds, and anti-extension exercises.","good":"Good anterior core endurance for their age. Continue developing through progressive loading — hollow body positions, dead bugs, and plank progressions.","average":"Average anterior hold time for their age. Focus on building endurance quality — hollow body, dead bugs, and front plank before adding external load.","needs_work":"Below average anterior core endurance for their age. Begin with supported positions, focus on breathing and tension quality, and progress duration before adding load."}},{"name":"Side Plank","unit":"s","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"The Side Plank test measures lateral core endurance — specifically the obliques, quadratus lumborum, and hip abductors working to resist lateral spinal flexion under sustained load.","why_it_matters":"Lateral core stability supports frontal-plane control during running, cutting, and landing. Directly linked to knee valgus reduction, hip stability, and injury resilience.","notes":"No published youth normative study exists for this test — practitioner benchmarks only, single age band 8-18.","commentary":{"elite":"","excellent":"Excellent lateral core endurance for trained youth. Continue developing with side plank variations and hip abductor strengthening.","good":"Good lateral core endurance for their age. Progress with side plank variations (with reach, hip dips) and include dedicated hip abductor work.","average":"Average lateral core endurance for their age. Focus on side plank quality and consistency, adding clamshells and lateral band walks.","needs_work":"Below average lateral core endurance for their age. Begin with modified side plank (from knees) and integrate glute medius activation work."}},{"name":"Grip Strength","unit":"kg","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"Grip strength measures the maximum isometric force of the hand and forearm flexors, tested using a hand dynamometer and expressed in kilograms.","why_it_matters":"Grip strength is a reliable proxy for overall upper body and systemic muscular strength in youth athletes. Predicts pulling capacity, carry strength, and general robustness.","notes":"","commentary":{"elite":"","excellent":"Excellent grip strength for their age. Strong upper body development — maintain through pulling movements, carries, and loaded gripping work.","good":"Good grip strength for their age. A solid foundation — continue with pulling movements and consider increasing pulling volume.","average":"Average grip strength for their age. Introduce pulling movements (rows, deadlifts, farmer carries) and specific grip training — dead hangs, plate pinches.","needs_work":"Below average grip strength for their age. Build pulling strength fundamentals — banded rows, inverted rows, dead hangs. Grip responds quickly to consistent loading."}},{"name":"Single Leg CMJ","unit":"cm","better_direction":"higher","requires_bodyweight":false,"is_bilateral":true,"screening_only":true,"what_it_measures":"Single Leg CMJ measures unilateral lower-body explosive power — each leg jumping independently. Used here purely as a left/right asymmetry screen.","why_it_matters":"Significant left-right asymmetry in single-leg power output is an established injury-risk marker, particularly for non-contact ACL and hamstring injuries.","notes":"No published youth normative data exists for Single Leg CMJ jump height itself, so it is never rated — shown for asymmetry screening only. Asymmetry benchmarks: <10% normal, 10-15% monitor, >15% clinical concern (Donskov et al. 2021).","commentary":{"elite":"","excellent":"","good":"","average":"","needs_work":""}},{"name":"CMJ Peak Force (kg)","unit":"kg","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"Peak propulsive force during the countermovement jump, from the force plate (both feet combined, in kg).","why_it_matters":"Used with IMTP peak force to work out the Dynamic Strength Index (DSI) - how much of an athlete's maximum strength they can express in a fast, dynamic movement.","notes":"Not rated on its own - used for DSI.","commentary":{}},{"name":"DSI (CMJ/IMTP)","unit":"","better_direction":"higher","requires_bodyweight":false,"is_bilateral":false,"screening_only":false,"what_it_measures":"The ratio of CMJ peak propulsive force to IMTP peak force (both in kg from the force plate, so bodyweight cancels out). It shows how much of an athlete's maximum strength is being expressed in a fast, ballistic movement.","why_it_matters":"DSI guides training emphasis. Below 0.60 suggests maximum strength is the limiter, so more strength work is warranted. Above 0.80 suggests dynamic output is near or beyond what the strength base predicts, so power and plyometric work becomes the priority. 0.60-0.80 means both qualities are developing in proportion.","notes":"Worked out automatically from CMJ Peak Force (kg) and IMTP Peak Force (kg) when both are logged. Zones from Suchomel et al. (2015) and Balsalobre-Fernandez et al. (2019); no published normative database exists, so it is zoned rather than rated.","commentary":{}}],"benchmarks":[{"metric":"10m Sprint","type":"elite_youth","sex":"female","min":null,"max":10,"avg":2.8,"good":2.65,"exc":2.5,"elite":2.35,"quality":"sparse","sources":"Extrapolated from Radnor et al. (2021); limited female U10 data"},{"metric":"10m Sprint","type":"general_population","sex":"female","min":null,"max":10,"avg":3.05,"good":2.8,"exc":2.65,"elite":2.5,"quality":"sparse","sources":"Extrapolated from Radnor et al. (2021); limited female U10 data"},{"metric":"Countermovement Jump","type":"elite_youth","sex":"female","min":null,"max":10,"avg":14,"good":18,"exc":22,"elite":27,"quality":"moderate","sources":"Taylor et al. (2010) n=1845; Radnor et al. (2021) adjusted"},{"metric":"Countermovement Jump","type":"general_population","sex":"female","min":null,"max":10,"avg":10,"good":14,"exc":18,"elite":22,"quality":"moderate","sources":"Taylor et al. (2010) n=1845; Radnor et al. (2021) adjusted"},{"metric":"Reactive Strength Index (10-5)","type":"elite_youth","sex":"female","min":null,"max":10,"avg":0.5,"good":0.7,"exc":0.9,"elite":1.15,"quality":"sparse","sources":"Baker & Read (2021) Aspire Academy; extrapolated to U10"},{"metric":"Reactive Strength Index (10-5)","type":"general_population","sex":"female","min":null,"max":10,"avg":0.3,"good":0.5,"exc":0.7,"elite":0.9,"quality":"sparse","sources":"Baker & Read (2021) Aspire Academy; extrapolated to U10"},{"metric":"IMTP Relative (N/kg)","type":"elite_youth","sex":"female","min":null,"max":10,"avg":11,"good":15,"exc":19,"elite":24,"quality":"sparse","sources":"Estimated from Morris et al. (2020); no validated female U10 IMTP data"},{"metric":"IMTP Relative (N/kg)","type":"general_population","sex":"female","min":null,"max":10,"avg":7,"good":11,"exc":15,"elite":19,"quality":"sparse","sources":"Estimated from Morris et al. (2020); no validated female U10 IMTP data"},{"metric":"10m Sprint","type":"elite_youth","sex":"female","min":11,"max":12,"avg":2.6,"good":2.45,"exc":2.3,"elite":2.17,"quality":"moderate","sources":"Radnor et al. (2021) EFL Academy (male-derived, adjusted); Nikolaidis et al. (2016)"},{"metric":"10m Sprint","type":"general_population","sex":"female","min":11,"max":12,"avg":2.85,"good":2.6,"exc":2.45,"elite":2.3,"quality":"moderate","sources":"Radnor et al. (2021) EFL Academy (male-derived, adjusted); Nikolaidis et al. (2016)"},{"metric":"Countermovement Jump","type":"elite_youth","sex":"female","min":11,"max":12,"avg":16,"good":20,"exc":24,"elite":29,"quality":"moderate","sources":"Taylor et al. (2010) n=1845 English school children; Radnor et al. (2021)"},{"metric":"Countermovement Jump","type":"general_population","sex":"female","min":11,"max":12,"avg":12,"good":16,"exc":20,"elite":24,"quality":"moderate","sources":"Taylor et al. (2010) n=1845 English school children; Radnor et al. (2021)"},{"metric":"Reactive Strength Index (10-5)","type":"elite_youth","sex":"female","min":11,"max":12,"avg":0.6,"good":0.8,"exc":1.05,"elite":1.3,"quality":"moderate","sources":"Baker & Read (2021) Aspire Academy 10-5 test; extrapolated to female"},{"metric":"Reactive Strength Index (10-5)","type":"general_population","sex":"female","min":11,"max":12,"avg":0.35,"good":0.6,"exc":0.8,"elite":1.05,"quality":"moderate","sources":"Baker & Read (2021) Aspire Academy 10-5 test; extrapolated to female"},{"metric":"IMTP Relative (N/kg)","type":"elite_youth","sex":"female","min":11,"max":12,"avg":13,"good":17,"exc":22,"elite":27,"quality":"sparse","sources":"Estimated from Morris et al. (2020) EFL Academy (male); no female U12 IMTP database"},{"metric":"IMTP Relative (N/kg)","type":"general_population","sex":"female","min":11,"max":12,"avg":9,"good":13,"exc":17,"elite":22,"quality":"sparse","sources":"Estimated from Morris et al. (2020) EFL Academy (male); no female U12 IMTP database"},{"metric":"10m Sprint","type":"elite_youth","sex":"female","min":13,"max":14,"avg":2.45,"good":2.28,"exc":2.14,"elite":2.01,"quality":"moderate","sources":"Radnor et al. (2021); Nikolaidis et al. (2016); female youth soccer data"},{"metric":"10m Sprint","type":"general_population","sex":"female","min":13,"max":14,"avg":2.68,"good":2.45,"exc":2.28,"elite":2.14,"quality":"moderate","sources":"Radnor et al. (2021); Nikolaidis et al. (2016); female youth soccer data"},{"metric":"Countermovement Jump","type":"elite_youth","sex":"female","min":13,"max":14,"avg":19,"good":23,"exc":27,"elite":32,"quality":"moderate","sources":"Taylor et al. (2010); Radnor et al. (2021); Meylan et al. (2009) female youth"},{"metric":"Countermovement Jump","type":"general_population","sex":"female","min":13,"max":14,"avg":14,"good":19,"exc":23,"elite":27,"quality":"moderate","sources":"Taylor et al. (2010); Radnor et al. (2021); Meylan et al. (2009) female youth"},{"metric":"Reactive Strength Index (10-5)","type":"elite_youth","sex":"female","min":13,"max":14,"avg":0.7,"good":0.95,"exc":1.2,"elite":1.5,"quality":"moderate","sources":"Baker & Read (2021); Lloyd et al. (2015) UK female youth"},{"metric":"Reactive Strength Index (10-5)","type":"general_population","sex":"female","min":13,"max":14,"avg":0.45,"good":0.7,"exc":0.95,"elite":1.2,"quality":"moderate","sources":"Baker & Read (2021); Lloyd et al. (2015) UK female youth"},{"metric":"IMTP Relative (N/kg)","type":"elite_youth","sex":"female","min":13,"max":14,"avg":17,"good":22,"exc":27,"elite":32,"quality":"moderate","sources":"Extrapolated Morris et al. (2020) + Meylan et al. (2012); limited female 13-14 IMTP data"},{"metric":"IMTP Relative (N/kg)","type":"general_population","sex":"female","min":13,"max":14,"avg":12,"good":17,"exc":22,"elite":27,"quality":"moderate","sources":"Extrapolated Morris et al. (2020) + Meylan et al. (2012); limited female 13-14 IMTP data"},{"metric":"10m Sprint","type":"elite_youth","sex":"female","min":15,"max":16,"avg":2.2,"good":2.05,"exc":1.94,"elite":1.83,"quality":"strong","sources":"Radnor et al. (2021) EFL Academy; Nikolaidis et al. (2016) female youth soccer n=248"},{"metric":"10m Sprint","type":"general_population","sex":"female","min":15,"max":16,"avg":2.45,"good":2.28,"exc":2.12,"elite":1.98,"quality":"strong","sources":"Radnor et al. (2021) EFL Academy; Nikolaidis et al. (2016) female youth soccer n=248"},{"metric":"Countermovement Jump","type":"elite_youth","sex":"female","min":15,"max":16,"avg":22,"good":26,"exc":31,"elite":36,"quality":"strong","sources":"Taylor et al. (2010) n=1845; Radnor et al. (2021); Meylan et al. (2009)"},{"metric":"Countermov